def match(pattern: str, text: str) -> bool:
    """
    Uses a recursive backtracking algorithm to implement basic regex matching.
    Supports literal characters, '.' (matches any single character), '*' (matches zero or more of the preceding element),
    and '+' (matches one or more of the preceding element).
    """
    def is_match(p_idx: int, t_idx: int) -> bool:
        # If the pattern is at the end, return True if the text is also at the end.
        if p_idx == len(pattern):
            return t_idx == len(text)

        # Check if current character matches or pattern is '.'
        current_match = (t_idx < len(text) and 
                         (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.'))

        # Handle '*' and '+' operators
        if p_idx + 1 < len(pattern):
            if pattern[p_idx + 1] == '*':
                # '*' can match no occurrences or one/more occurrences of the preceding character
                return (is_match(p_idx + 2, t_idx) or  # match zero occurrences
                        (current_match and is_match(p_idx, t_idx + 1)))  # match one or more occurrences

            elif pattern[p_idx + 1] == '+':
                # '+' requires at least one occurrence of the preceding character
                if current_match:
                    return is_match(p_idx, t_idx + 1)  # match one or more occurrences

        # Proceed with the next character if there's a match
        return current_match and is_match(p_idx + 1, t_idx + 1)

    return is_match(0, 0)

